def median_of_two(a: list[int], b: list[int]) -> float:
    if len(a) > len(b):
        a, b = b, a                              # binary search the shorter list
    total = len(a) + len(b)
    half = (total + 1) // 2                      # how many values go left of the cut
    lo, hi = 0, len(a)
    while True:
        i = (lo + hi) // 2                       # values taken from a
        j = half - i                             # values taken from b
        a_left = a[i - 1] if i > 0 else float("-inf")
        a_right = a[i] if i < len(a) else float("inf")
        b_left = b[j - 1] if j > 0 else float("-inf")
        b_right = b[j] if j < len(b) else float("inf")
        if a_left > b_right:
            hi = i - 1                           # took too many from a
        elif b_left > a_right:
            lo = i + 1                           # took too few from a
        else:
            left_max = max(a_left, b_left)
            if total % 2:
                return float(left_max)
            return (left_max + min(a_right, b_right)) / 2
